content.text:
    lessonComplete?: boolean;
    objectiveChecks?: ObjectiveCheck[];
    sourceCoverage?: SourceCoverageItem[];
    coverageUpdates?: CoverageUpdate[];
    figureReviews?: unknown[];
    findingResponses?: FindingResponse[];
  },
  requireLearnSection: (book: ScholarBook) => ScholarSection,
  mutateBook: MutateBook,
  toolResult: ToolResultFn,
  config?: ScholarConfig,
  deferCommit = false,
): Promise<{ content: Array<{ type: "text"; text: string }>; details: ToolDetails }> {
  const synthesis = params.synthesis?.trim();
  const keyPoints = compactStrings(params.keyPoints);
  if (params.lesson && params.lessonPatch) throw new Error("Use either lesson or lessonPatch in one notes call, not both.");
  if (params.sourceCoverage && params.coverageUpdates) throw new Error("Use sourceCoverage or coverageUpdates in one notes call, not both.");
  if (params.findingResponses !== undefined) {
    if (!Array.isArray(params.findingResponses) || !params.findingResponses.length || !params.findingResponses.every(isFindingResponse)) {
      throw new Error("findingResponses must be an array of valid responses with key, action ('fixed' | 'declined'), and note (1-600 chars).");
    }
  }
  if (![params.lesson, params.lessonPatch, params.lessonComplete, params.sourceCoverage, params.coverageUpdates, params.figureReviews,
    params.synthesis, params.keyPoints, params.objectives, params.coveredObjectives, params.objectiveChecks, params.requiredChecks, params.misconceptions, params.findingResponses].some(value => value !== undefined)) {
    throw new Error("Nothing saved. Supply a lesson, recap, source plan, figureReviews, objectiveChecks, coverageUpdates or findingResponses. These fields may be saved independently.");
  }
  if (session.mode === "tutor") {
    if (!session.recordId) throw new Error("No Tutor session is active.");
    const mutation = await mutateBook(book.id, (state) => {
      const tutor = state.tutorSessions.find((item) => item.id === session.recordId);
      if (!tutor || tutor.status !== "active") throw new Error("The active Tutor session is missing or closed.");
      if (synthesis) tutor.synthesis = synthesis;
      tutor.keyPoints = compactStrings([...tutor.keyPoints, ...keyPoints, ...(params.lesson?.keyPoints || [])]);
      if (params.lesson) saveLesson(tutor, state, params.lesson, config);
      if (params.lessonPatch) patchLesson(tutor, state, params.lessonPatch, config);
      if (params.findingResponses?.length) {
        if (!tutor.review) tutor.review = { version: 1, receipts: [], responses: [] };
        const existing = new Map((tutor.review.responses || []).map(r => [r.key, r]));
        for (const resp of params.findingResponses) existing.set(resp.key, resp);
        tutor.review.responses = [...existing.values()];
      }
      tutor.updatedAt = new Date().toISOString();
    });
    return toolResult("notes", `Saved source-grounded Tutor notes for ${mutation.book.tutorSessions.find((item) => item.id === session.recordId)?.title}.`, { bookId: book.id });
  }
  const activeSection = requireLearnSection(book);
  const sectionId = activeSection.id;
  if (params.sectionId && params.sectionId !== sectionId && params.sectionId !== activeSection.number) {
    throw new Error(`Scholar Learn notes must target the frozen Learn section ${sectionId} (${activeSection.number}). Omit sectionId to use it; this call saved nothing.`);
  }
  const objectives = params.objectives === undefined ? activeSection.objectives : compactStrings(params.objectives);
  const covered = compactStrings(params.coveredObjectives);
  if (objectives.length === 0) throw new Error("Nothing saved. Declare the section's source-grounded objectives in the top-level objectives field of action=notes. lesson.objectives and objectiveChecks reference that declaration; they do not create it. After declaration, omit objectives to preserve them. Retry the intended notes fields after fixing this declaration; do not call outline.");
  const unknownCovered = covered.filter((objective) => !objectives.includes(objective));
  if (unknownCovered.length) throw new Error(`Covered objectives must exactly match declared objectives: ${unknownCovered.join("; ")}`);
  const mutation = await mutateBook(book.id, (state) => {
    const section = findSection(state, sectionId);
    if (!section) throw new Error(`Unknown Scholar section: ${sectionId}`);
    const editorial = Boolean(section.learnQuality && section.status !== "complete"
      && !section.attempts.some(attempt => attempt.grounding?.purpose !== "diagnostic"));
    const sameMembers = (left: string[], right: string[]) => left.length === right.length && left.every((value) => right.includes(value));
    if (section.status === "complete" && (
      !sameMembers(objectives, section.objectives)
      || (params.coveredObjectives !== undefined && !sameMembers(covered, section.coveredObjectives))
      || (params.requiredChecks !== undefined && !sameMembers(requiredChecks(params.requiredChecks), requiredChecks(section.requiredChecks)))
    )) {
      throw new Error("This section is complete; practice cannot change its earned objective coverage or required checks. Keep those fields unchanged when saving practice notes.");
    }
    // Completion requires covering every declared objective, so a shrinking
    // declaration would certify the section by lowering the bar: declare five,
    // teach one, redeclare that one, complete. Once teaching has begun the
    // declared set may grow but never lose or reword an entry — grounding
    // receipts also cite these strings verbatim, so a rewrite would silently
    // invalidate the basis of every question already asked.
    const retired = section.objectives.filter((objective) => !objectives.includes(objective));
    if (section.status !== "not-started" && retired.length > 0) {
      throw new Error(
        `Scholar Learn objectives are fixed once teaching begins, and completion requires covering all of them. `
        + `This call drops ${retired.length} already-declared objective(s): ${retired.join("; ")}. `
        + `Include them again — add to coveredObjectives as you teach them. To state one more clearly, keep the original text and append the clearer version as a new objective.`,
      );
    }
    section.objectives = objectives;
    const sourceCoverage = params.coverageUpdates ? updateCoverageEvidence(section.learnQuality?.coverage || [], params.coverageUpdates) : params.sourceCoverage;
    if (sourceCoverage !== undefined) {
      if (section.status === "complete" && JSON.stringify(sourceCoverage) !== JSON.stringify(section.learnQuality?.coverage)) throw new Error("Practice cannot adopt or replace the completed section's source coverage contract.");
      const rawCoverage: unknown = sourceCoverage;
      if (!isSourceCoverageLedger(rawCoverage)) {
        const invalid = Array.isArray(rawCoverage) ? rawCoverage.flatMap((item, index) =>
          isSourceCoverageItem(item) ? [] : [`${index + 1}${typeof item?.id === "string" ? ` (${item.id})` : ""}`]) : [];
        throw new Error(`Nothing saved. Invalid sourceCoverage ${invalid.length ? `item(s): ${invalid.join(", ")}` : "checklist (expected an array with unique IDs)"}. Each item needs id, kind, description, sourcePages and objective. Optional IDs must be nonempty identifiers; optional evidence must be a nonempty exact passage. Omit unused optional fields. Equation and snapshot references may accompany any item, but must identify content rendered in that lesson at completion. Correct those fields and retry; do not discard the lesson or change its objectives.`);
      }
      const issues = sourceCoverageIssues(sourceCoverage, { ...section, lessons: [] });
      if (issues.length) throw new Error(`Repair the source coverage plan: ${issues.join("; ")}`);
      section.learnQuality ||= { version: 1, coverage: [], reviews: [] };
      section.learnQuality.coverage = sourceCoverage;
    }
    if (params.objectiveChecks !== undefined) {
      if (!isObjectiveChecks(params.objectiveChecks) || params.objectiveChecks.some(item => !objectives.includes(item.objective))) throw new Error("objectiveChecks must map declared objectives to nonempty conceptual/application/computation/discrimination checks.");
      const changed = (section.objectiveChecks || []).some(old => !params.objectiveChecks!.some(next => next.objective === old.objective && old.checks.every(kind => next.checks.includes(kind))));
      if (changed && !editorial) throw new Error("Keep existing objective checks; do not lower the mastery requirements after teaching starts.");
      if (section.status === "complete" && JSON.stringify(params.objectiveChecks) !== JSON.stringify(section.objectiveChecks)) throw new Error("Practice cannot change the completed section's objective checks.");
      section.objectiveChecks = params.objectiveChecks;
    }
    const checks = params.requiredChecks === undefined
      ? requiredChecks(editorial && params.objectiveChecks ? params.objectiveChecks.flatMap(item => item.checks) : section.requiredChecks) : requiredChecks(params.requiredChecks);
    const droppedChecks = section.requiredChecks.filter((kind) => !checks.includes(kind));
    if (!editorial && section.status !== "not-started" && droppedChecks.length > 0) {
      throw new Error(`Scholar Learn checks are fixed once teaching begins. Keep these required checks: ${droppedChecks.join(", ")}.`);
    }
    section.requiredChecks = requiredChecks([...checks, ...(section.objectiveChecks || []).flatMap(item => item.checks)]);
    if (synthesis) section.synthesis = synthesis;
    section.keyPoints = compactStrings([...(editorial && params.keyPoints !== undefined ? [] : section.keyPoints), ...keyPoints, ...(params.lesson?.keyPoints || [])]);
