// Throwaway: confirms the rewritten audit-as-you-go sentences render in Learn and Tutor policies.
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import { extensionPath, piPackageRoot, jitiPath } from "./tests/sdk.mjs";

const { createJiti } = await import(pathToFileURL(jitiPath));
const jiti = createJiti(import.meta.url, { moduleCache: false,
  alias: { "@earendil-works/pi-coding-agent": join(piPackageRoot, "dist/index.js") } });
const { learnInstructions, tutorInstructions } = await jiti.import(join(dirname(extensionPath), "policies.ts"));

const book = { metadata: { title: "Smoke fixture" },
  chapters: [{ number: "1", sections: [{ id: "s1", number: "1.1", title: "Vectors", order: 1, startPage: 1, endPage: 1, transcript: [] }] }] };
const learn = learnInstructions(book, book.chapters[0].sections[0]);
const tutor = tutorInstructions(book, { id: "t1", scope: { description: "fixture", chapterIds: [], sectionIds: [] }, transcript: [] });

const want = [
  [learn, /Each saved explanation revision is audited once, as it is saved, while you continue authoring/, "learn audit-once"],
  [learn, /Unresolved blocking findings arrive on your next Scholar tool result as \[F-<key>\] blocks/, "learn findings ride next result"],
  [learn, /lessonComplete waits only for the outstanding audits of the current revisions/, "learn lessonComplete wait"],
  [learn, /findingResponses: \[\{ key, action: 'fixed' \| 'declined', note \}\]/, "learn findingResponses"],
  [learn, /an unresolved rejected revision is not audited again/, "learn no re-audit"],
  [tutor, /Each saved tutor explanation revision is audited once, as it is saved/, "tutor audit-once"],
  [tutor, /unresolved blocking findings arrive on your next Scholar tool result as \[F-<key>\] blocks/, "tutor findings ride next result"],
  [tutor, /Every practice\/mastery question is independently reviewed before delivery/, "tutor question review"],
];
const dont = [
  [learn, /automatically runs independent source, teaching and math\/visual reviews/],
  [learn, /resubmission after findings checks your recorded findingResponses instead of running the crew again/],
  [learn, /An interrupted, stale or unavailable review is never an approval/],
  [tutor, /Saved tutor explanations and every practice\/mastery question are independently reviewed before delivery/],
  [learn, /crew/], [tutor, /crew/],
];
let failed = 0;
for (const [text, pattern, name] of want) {
  const ok = pattern.test(text);
  if (!ok) failed++;
  console.log(`[${ok ? "PASS" : "FAIL"}] ${name}`);
}
for (const [text, pattern] of dont) {
  const hit = pattern.test(text);
  if (hit) failed++;
  console.log(`[${hit ? "FAIL" : "PASS"}] stale text absent: ${pattern}`);
}
console.log(failed ? `\n${failed} failed` : "\nall policy text checks passed");
process.exitCode = failed ? 1 : 0;

